define(["core/ajax","core/notification","core/str"],function(Ajax,Notification,Str){const viewed=new Set;const queued=new Set;const timers=new Map;let flushTimer=null;const updateProgress=function(result){document.querySelectorAll("[data-region='progress']").forEach(function(region){const bar=region.querySelector(".progress-bar");const progress=region.querySelector(".progress");const label=region.querySelector("[data-region='progress-label']");const percentage=Math.round(result.percentage);if(bar){bar.style.width=percentage+"%"}if(progress){progress.setAttribute("aria-valuenow",percentage)}if(label){label.textContent=percentage+"%"}});if(result.activitycompleted){Str.get_string("activitycompletedmessage","mod_bookflow").then(function(message){const region=document.querySelector(".bookflow-reader-progress");if(region&&!region.querySelector(".alert-success")){const notice=document.createElement("div");notice.className="alert alert-success mt-2";notice.setAttribute("role","status");notice.textContent=message;region.appendChild(notice)}return message}).catch(Notification.exception)}};const flush=function(bookflowId){if(flushTimer){window.clearTimeout(flushTimer)}flushTimer=null;const contentIds=Array.from(queued);queued.clear();if(!contentIds.length){return}Ajax.call([{methodname:"mod_bookflow_mark_contents_viewed",args:{bookflowid:bookflowId,contentids:contentIds}}])[0].then(updateProgress).catch(Notification.exception)};const queueViewed=function(bookflowId,contentId){if(viewed.has(contentId)){return}viewed.add(contentId);queued.add(contentId);if(!flushTimer){flushTimer=window.setTimeout(function(){flush(bookflowId)},800)}};const complete=function(bookflowId,contentId,metric,details){return Ajax.call([{methodname:"mod_bookflow_mark_content_completed",args:{bookflowid:bookflowId,contentid:contentId,metric:metric,details:JSON.stringify(details||{})}}])[0].then(updateProgress).catch(Notification.exception)};const savePosition=function(bookflowId,chapterId,contentId){Ajax.call([{methodname:"mod_bookflow_save_user_position",args:{bookflowid:bookflowId,chapterid:chapterId,contentid:contentId,scrollposition:Math.max(0,Math.round(window.scrollY))}}])[0].catch(Notification.exception)};const init=function(bookflowId,chapterId){const blocks=document.querySelectorAll(".bookflow-content[data-track-progress='1']");const positionBlocks=document.querySelectorAll(".bookflow-content");const observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){const block=entry.target;const contentId=Number(block.dataset.contentId);const completionType=block.dataset.completionType;const completionValue=Number(block.dataset.completionValue||0);if(entry.isIntersecting&&entry.intersectionRatio>=.5){queueViewed(bookflowId,contentId);if(completionType==="timed"&&!timers.has(contentId)){flush(bookflowId);const timer=window.setTimeout(function(){complete(bookflowId,contentId,100,{visibleSeconds:completionValue});timers.delete(contentId)},(Math.max(1,completionValue)+1)*1e3);timers.set(contentId,timer)}}else if(timers.has(contentId)){window.clearTimeout(timers.get(contentId));timers.delete(contentId)}})},{threshold:[.5]});blocks.forEach(function(block){observer.observe(block)});const positionObserver=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting&&entry.intersectionRatio>=.5){savePosition(bookflowId,chapterId,Number(entry.target.dataset.contentId))}})},{threshold:[.5]});positionBlocks.forEach(function(block){positionObserver.observe(block)});document.addEventListener("click",function(event){const manual=event.target.closest("[data-action='bookflow-complete-manual']");if(manual){complete(bookflowId,Number(manual.dataset.contentId),100,{manual:true})}})};return{init:init,complete:complete,updateProgress:updateProgress}});